output_text:
[
  {
    "id": "must_collect_entry_cart",
    "text": "A shopper is obliged to collect the entrance cart from the cart depot before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_depot": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "collect_entry_cart": {
          "pre": {
            "and": [
              "entrance_cart_depot",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "collect_entry_cart"
    }
  },
  {
    "id": "no_bare_hand_item_pickup",
    "text": "A shopper is forbidden to pick up shelf items unless they are currently using a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "bare_hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "bare_hand_item_pickup"
    }
  },
  {
    "id": "return_cart_to_front_bay",
    "text": "After taking the entrance cart, the shopper is obliged to return or leave it at the front return bay before leaving the store.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "collect_entry_cart": {
          "pre": {
            "and": [
              "at(1,5)",
              "cartAt(1,5)",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "hasCart",
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "collect_entry_cart",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "no_cart_abandonment_elsewhere",
    "text": "A shopper is forbidden to leave a cart anywhere other than the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "away_from_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "leave_cart_outside_bay": {
          "pre": {
            "and": [
              "hasCart",
              "LEAVE_CART",
              "away_from_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_bay"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is forbidden to take a cart through the store exit.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "using_cart": "hasCart"
      },
      "events": {
        "exit_attempt_with_cart": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT",
              "using_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_attempt_with_cart"
    }
  },
  {
    "id": "no_carts_in_checkout_corridor",
    "text": "Carts are forbidden in the checkout and exit corridor, so shoppers must enter that corridor only after parking the cart.",
    "abstraction": {
      "state_properties": {
        "checkout_corridor": {
          "or": [
            "at(2,2)",
            "at(3,2)",
            "at(4,2)",
            "at(5,2)",
            "at(6,2)",
            "at(7,2)",
            "at(8,2)",
            "at(9,2)",
            "at(8,3)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "cart_in_checkout_corridor": {
          "and": [
            "hasCart",
            "checkout_corridor"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_checkout_corridor"
    }
  },
  {
    "id": "exit_after_cart_return",
    "text": "Once the cart has been returned at the front bay, the shopper is obliged to proceed to the exit rather than resume shopping with the cart.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "exit_cell": "at(9,5)"
      },
      "events": {
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "hasCart",
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        },
        "exit_store": {
          "pre": {
            "and": [
              "exit_cell",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "return_cart_to_bay",
      "discharge": "exit_store"
    }
  },
  {
    "id": "no_cart_past_far_shelf",
    "text": "When using a cart at the far shelf around (6,4), the shopper is forbidden to continue east or south into the service-side aisle and must turn back.",
    "abstraction": {
      "state_properties": {
        "far_shelf_cell": "at(6,4)",
        "service_side_cells": {
          "or": [
            "at(7,4)",
            "at(8,4)"
          ]
        },
        "cart_in_service_side_cells": {
          "and": [
            "hasCart",
            "service_side_cells"
          ]
        }
      },
      "events": {
        "cart_goes_east_from_far_shelf": {
          "pre": {
            "and": [
              "hasCart",
              "far_shelf_cell",
              "E"
            ]
          },
          "post": null
        },
        "cart_goes_south_from_far_shelf": {
          "pre": {
            "and": [
              "hasCart",
              "far_shelf_cell",
              "S"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "cart_goes_east_from_far_shelf",
          "cart_goes_south_from_far_shelf",
          "cart_in_service_side_cells"
        ]
      }
    }
  }
]
